<table class="meta"><tr><td><b><?php echo e($i['number']); ?></b> · <?php echo e($i['time']); ?><br><?php echo e($i['customer']); ?></td><td class="right"><?php echo e(ucfirst($i['status'])); ?><br>Paid: <?php echo e($money($i['paid'])); ?> · Balance: <?php echo e($money($i['balance'])); ?></td></tr></table>
