<h2>05 / Payment transaction register</h2><table><thead><tr><th>Time / ID</th><th>Invoice / customer</th><th>Method / direction</th><th>Reference</th><th class="right">Amount</th></tr></thead><tbody><?php $__empty_1 = true; $__currentLoopData = $report['payments']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $p): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><tr><td><?php echo e(substr($p['time'],11)); ?><br>#<?php echo e($p['id']); ?><?php if(!empty($p['payment_date'])): ?><br>Paid: <?php echo e($p['payment_date']); ?><?php endif; ?></td><td><?php echo e($p['invoice']); ?><br><?php echo e($p['customer']); ?></td><td><?php echo e($labels[$p['method']] ?? $p['method']); ?><br><?php echo e(ucfirst($p['direction'])); ?></td><td><?php echo e($p['reference'] ?? '—'); ?></td><td class="right"><?php echo e($money($p['amount'])); ?></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><tr><td colspan="5">No payment transactions.</td></tr><?php endif; ?></tbody></table>
